'use strict';
const KEY='fab-plant-care-prototype-v1';
const $=id=>document.getElementById(id);
let plants=[], selected=null, editing=null, failNext=false, busy=false, listScroll=0, loadError=false;
try {const raw=localStorage.getItem(KEY); if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.reminder==='string'&&Array.isArray(p.waterings)&&p.waterings.every(w=>typeof w.id==='string'&&typeof w.at==='string'&&Number.isFinite(Date.parse(w.at)))))throw Error();plants=data;}}catch{loadError=true;}
function el(tag,text){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;}
function button(text,fn){const n=el('button',text);n.type='button';n.onclick=fn;return n;}
function stamp(at){return new Date(at).toLocaleString('ru-RU');}
function message(text){$('message').textContent=text;}
function render(){const root=$('screen');root.replaceChildren();if(selected){const p=plants.find(p=>p.id===selected);root.append(button('Назад к списку',()=>{selected=null;render();window.scrollTo(0,listScroll);}),el('h1',p.name),el('p',p.reminder?'Напоминание: '+p.reminder:'Напоминание не задано'),button('Изменить данные',()=>openForm(p)),el('h2','История поливов'));if(!p.waterings.length)root.append(el('p','Поливов пока нет.'));const ul=el('ul');for(const w of [...p.waterings].reverse()){const li=el('li');li.append(el('p','Полив: '+stamp(w.at)),button('Удалить ошибочную запись',()=>mutate(next=>{const target=next.find(x=>x.id===p.id);target.waterings=target.waterings.filter(x=>x.id!==w.id);},'Удалена ошибочная запись полива от '+stamp(w.at)+'.')));ul.append(li);}root.append(ul);}else{root.append(el('h1','Мои растения'),button('Добавить растение',()=>openForm()));if(!plants.length)root.append(el('p','Растений пока нет. Добавь первое растение.'));for(const p of plants){const row=el('article');row.append(el('h2',p.name),el('p',p.reminder||'Напоминание не задано'),el('p',p.waterings.length?'Последний полив: '+stamp(p.waterings.at(-1).at):'Поливов пока нет.'));const actions=el('div');actions.className='actions';actions.append(button('Открыть карточку',()=>{listScroll=window.scrollY;selected=p.id;message('');render();window.scrollTo(0,0);}),button('Отметить полив',()=>mutate(next=>next.find(x=>x.id===p.id).waterings.push({id:crypto.randomUUID(),at:new Date().toISOString()}),'Полив растения «'+p.name+'» сохранён.')));row.append(actions);root.append(row);}}}
function save(next){if(loadError)throw Error('Сохранение заблокировано: существующие данные повреждены или хранилище недоступно.');if(failNext){failNext=false;$('armed').textContent='';throw Error('Тестовая ошибка сохранения. Повтори попытку.');}localStorage.setItem(KEY,JSON.stringify(next));plants=next;}
function mutate(change,success){if(busy)return;busy=true;try{const next=structuredClone(plants);change(next);save(next);render();message(success);}catch(e){message('Не сохранено. '+e.message);}finally{busy=false;}}
function openForm(p){editing=p?p.id:null;$('formTitle').textContent=p?'Изменить растение':'Добавить растение';$('submit').textContent=p?'Сохранить':'Создать';$('name').value=p?p.name:'';$('reminder').value=p?p.reminder:'';$('formError').textContent='';message('');$('sheet').showModal();$('name').focus();}
$('cancel').onclick=()=>$('sheet').close();
$('sheet').addEventListener('click',e=>{if(e.target===$('sheet')){const r=$('sheet').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('sheet').close();}});
$('form').onsubmit=e=>{e.preventDefault();if(busy)return;const name=$('name').value.trim(),reminder=$('reminder').value;if(!name){$('formError').textContent='Укажи непустое название.';$('name').focus();return;}busy=true;$('submit').disabled=true;try{const next=structuredClone(plants);if(editing){Object.assign(next.find(p=>p.id===editing),{name,reminder});}else next.push({id:crypto.randomUUID(),name,reminder,waterings:[]});save(next);$('sheet').close();render();message(editing?'Изменения сохранены.':'Растение создано.');}catch(e){$('formError').textContent='Не сохранено. '+e.message;}finally{busy=false;$('submit').disabled=false;}};
$('fail').onclick=()=>{failNext=!failNext;$('armed').textContent=failNext?' Следующее сохранение завершится ошибкой.':'';};
render();if(loadError)message('Не удалось прочитать сохранённые данные. Перезапись заблокирована, исходные данные не изменены.');
